-- 신조어 7개 승격 (2026-09-04 아침 검수, 운영자 승인).
-- slang_candidates(status='native_review_pending')에서 승인된 후보의 draft_payload를 그대로 words로 옮긴다.
-- 승인: 영크크, 늙크크, 어그로, 삼귀다, 관종, 국룰, 낄끼빠빠
-- 보류: 커터칼퇴(뜻 갈림), 뉴아르(2023년 등장, 신선도 미달), 얼렁뚱땡이, '올크크' 별도 표제어
--
-- 검수 메모:
--  * 늙크크 — 준말 해석이 출처마다 갈려(늙은 크크크 vs 영크크 대칭형) origin에 두 설 병기.
--    이형태 '올크크'는 별도 표제어로 등록하지 않고 정의 안 언급만(운영자 지시로 보류).
--  * 영크크/늙크크 — 한 쌍이라 함께 등록. 어원은 코르티스(CORTIS) 곡 Young Creator Crew.
--  * 관종 — 준말 원형이 '관심종자'인지 '관심병 종자'인지 갈려 둘 다 병기. 최초 연도는
--    어느 출처에도 명시가 없어 '2010년대 초'로만 기술(운영자 확인 대기 중인 값).
--  * 어그로 — aggression/aggro 유래설도 영어권에 있어 aggravation만 확정 표기.
--
-- payload는 jsonb_populate_record로 words 컬럼에 매핑한다(컬럼 키가 1:1로 일치).
-- 문자열은 dollar-quoting($json$)이라 따옴표를 이중화하지 않는다.
--
-- NOTE: filename timestamp differs from the production migration version
-- (MCP apply time becomes the version) — repo-wide convention, see CLAUDE.md.

begin;

insert into public.words select * from jsonb_populate_record(null::public.words, $json${"id": "220", "word": "영크크", "likes": 0, "saves": 0, "usage": "유행에 밝은 사람을 칭찬하거나 가볍게 놀리듯 부를 때 쓴다. 늙크크와 짝을 이뤄 서로를 분류하는 놀이처럼 쓰이는 경우가 많다.", "origin": "보이그룹 코르티스(CORTIS)의 곡 Young Creator Crew(YCC)와 그룹이 쓰던 이 표현을 한국식으로 줄여 부르면서 2026년 온라인에 퍼졌다. 반대말로 늙크크·올크크가 파생됐다. 어느 커뮤니티에서 처음 줄여 썼는지는 확인되지 않았다.", "category": "new-slang", "meanings": [{"type": "명사", "examples": [{"de": "Du kennst das Meme schon? Voll der Trend-Native.", "es": "¿Ya conoces este meme? Eres un nativo de tendencias.", "ja": "え、このミームもう知ってるの?完全にヨンククじゃん。", "vi": "Ủa bạn biết meme này rồi à? Đúng dân bắt trend luôn.", "eng": "You already know this meme? Total trend native.", "kor": "야 너 이 밈 벌써 알아? 완전 영크크네."}, {"de": "Meine Teamleiterin ist ein Trend-Native - kennt den Slang besser als ich.", "es": "Mi jefa es nativa de tendencias: se sabe la jerga mejor que yo.", "ja": "うちのチーム長ヨンククで、流行語を私より詳しい。", "vi": "Sếp mình là dân bắt trend, rành tiếng lóng hơn cả mình.", "eng": "My team lead is a trend native - knows the slang better than I do.", "kor": "우리 팀장님 영크크라 유행어 나보다 잘 아심."}], "definition": "최신 밈·유행어·챌린지를 설명 없이 바로 알아듣고 즐기는 사람. 핵심은 실제 나이가 아니라 감각이라, 40대여도 유행에 밝으면 영크크고 20대여도 말투가 굳어 있으면 영크크가 아니다.", "definition_i18n": {"de": "Jemand, der die neuesten Memes, Slang-Wörter und Challenges sofort versteht, ohne Erklärung. Entscheidend ist die Haltung, nicht das Alter: Ein aufgeweckter 40-Jähriger zählt dazu, ein steifer 20-Jähriger nicht.", "en": "Someone who gets the newest memes, slang and challenges without needing them explained. The point is vibe, not age: a switched-on 40-year-old counts as one, while a stiff 20-year-old does not.", "es": "Alguien que capta los memes, la jerga y los retos más nuevos sin que se los expliquen. Lo que cuenta es la onda, no la edad: un cuarentón enterado lo es, y un veinteañero acartonado no.", "ja": "最新のミーム・流行語・チャレンジを説明なしですぐ理解して楽しむ人。基準は実年齢ではなく感覚なので、40代でも流行に詳しければヨンククだし、20代でも話し方が硬ければ違う。", "vi": "Người hiểu ngay meme, tiếng lóng, thử thách mới nhất mà không cần ai giải thích. Quan trọng là chất, không phải tuổi: người 40 mà bắt trend vẫn tính, còn người 20 mà cứng nhắc thì không."}}], "created_at": "2026-09-04T08:00:00+00:00", "short_desc": "요즘 유행을 바로 알아듣는 감각 좋은 사람", "usage_i18n": {"de": "Um jemanden zu loben - oder leicht zu necken -, der Trends kennt; oft im Paar mit neukkeukeu als Spiel, sich gegenseitig einzuordnen.", "en": "Used to compliment - or lightly tease - someone who is on top of trends; often paired with neukkeukeu as a game of sorting people.", "es": "Se usa para elogiar -o picar suavemente- a quien va al día; suele emparejarse con neukkeukeu como un juego de clasificarse.", "ja": "流行に詳しい人を褒めたり軽くからかったりするときに使う。ヌルククと対にして互いを分類する遊びのように使われることが多い。", "vi": "Dùng để khen - hoặc trêu nhẹ - người rành trend; hay đi cặp với neukkeukeu như trò phân loại nhau."}, "origin_i18n": {"de": "Von der Boygroup CORTIS und ihrem Song Young Creator Crew (YCC); koreanische Nutzer kürzten die Phrase zu einem dreisilbigen Spitznamen, der sich 2026 online verbreitete. Daraus entstanden die Gegenbegriffe neukkeukeu und olkeukeu. Welche Community zuerst kürzte, ist unbestätigt.", "en": "From the boy group CORTIS and their song Young Creator Crew (YCC); Korean users clipped the phrase into a three-syllable nickname, which spread online in 2026. The antonyms neukkeukeu and olkeukeu grew out of it. Which community first clipped it is unverified.", "es": "Del grupo CORTIS y su tema Young Creator Crew (YCC); los usuarios coreanos recortaron la frase a un apodo de tres sílabas que se difundió en 2026. De ahí salieron los antónimos neukkeukeu y olkeukeu. Qué comunidad lo recortó primero no está verificado.", "ja": "ボーイグループCORTISの曲Young Creator Crew(YCC)と、グループが使っていたこの表現を韓国式に縮めて呼んだことから2026年にオンラインで広まった。反対語としてヌルククとオルククが派生。どのコミュニティが最初に縮めたかは未確認。", "vi": "Từ nhóm nhạc nam CORTIS và ca khúc Young Creator Crew (YCC); người dùng Hàn rút gọn cụm này thành biệt danh ba âm tiết, lan rộng trên mạng năm 2026. Từ đó sinh ra các từ trái nghĩa neukkeukeu và olkeukeu. Chưa rõ cộng đồng nào rút gọn đầu tiên."}, "romanization": "Yeong-keu-keu", "translations": [{"lang": "🇺🇸 EN", "text": "Trend native (someone who gets it instantly)"}, {"lang": "🇯🇵 JA", "text": "最新の流行に敏感な人"}, {"lang": "🇨🇳 ZH", "text": "紧跟潮流的人"}, {"lang": "🇻🇳 VI", "text": "Người bắt trend rất nhanh"}, {"lang": "🇪🇸 ES", "text": "Nativo de tendencias"}, {"lang": "🇩🇪 DE", "text": "Trend-Native"}], "pronunciation": "[영크크]", "related_words": ["늙크크", "인싸", "핵인싸"], "short_desc_i18n": {"de": "Jemand, der aktuelle Trends sofort versteht", "en": "Someone who instantly gets the latest trends", "es": "Alguien que pilla las tendencias al instante", "ja": "最新の流行をすぐ理解する感覚のいい人", "vi": "Người bắt trend mới nhất ngay lập tức"}}$json$::jsonb);

insert into public.words select * from jsonb_populate_record(null::public.words, $json${"id": "221", "word": "늙크크", "likes": 0, "saves": 0, "usage": "새 밈을 못 알아들었을 때 자조적으로 쓴다. 남에게 쓰면 놀리는 뉘앙스이므로 친한 사이가 아니면 조심하는 편이 좋다.", "origin": "코르티스(CORTIS)의 곡 Young Creator Crew에서 나온 영크크에 늙-을 붙여 만든 반대말로, 2026년 온라인 밈으로 퍼졌다. 늙은 크크크의 준말이라는 풀이도 돌지만, 영크크의 대칭형으로 보는 설명이 더 널리 쓰이며 어느 쪽이 맞는지는 확정되지 않았다.", "category": "new-slang", "meanings": [{"type": "명사", "examples": [{"de": "Was heißt das überhaupt? Ich bin echt abgehängt.", "es": "¿Y esto qué significa? Estoy totalmente desconectada.", "ja": "これどういう意味?私、本当にヌルククかも。", "vi": "Cái này nghĩa là gì vậy? Chắc mình lạc hậu thật rồi.", "eng": "What does this even mean? I really am out of the loop.", "kor": "이게 무슨 뜻이야? 나 진짜 늙크크인가 봐."}, {"de": "Ich verstehe keinen einzigen Kommentar. Okay, ich bin abgehängt.", "es": "No entiendo ni un comentario. Vale, estoy desconectada.", "ja": "コメントが一つも分からない。ヌルクク認めます。", "vi": "Không hiểu nổi một bình luận nào. Thôi công nhận mình lạc hậu.", "eng": "I cannot follow a single comment. Fine, I am out of the loop.", "kor": "댓글 하나도 못 알아듣겠어. 늙크크 인정한다."}], "definition": "최신 밈이나 유행어를 못 알아듣는 사람. 올크크라고도 한다. 실제 나이와 무관해서 10대여도 유행에 뒤처지면 늙크크가 되며, 남을 놀릴 때보다 못 알아들은 자신을 낮춰 부를 때 훨씬 많이 쓴다.", "definition_i18n": {"de": "Jemand, der die neuesten Memes oder Slang-Wörter nicht versteht; auch olkeukeu genannt. Das Alter spielt keine Rolle - auch ein abgehängter Teenager zählt dazu - und man benutzt es viel öfter für sich selbst, nachdem man einen Witz nicht verstanden hat, als zum Spott über andere.", "en": "Someone who does not get the latest memes or slang; also called olkeukeu. Age is beside the point - a teenager who is behind counts too - and it is used far more to label yourself after missing a joke than to mock anyone else.", "es": "Alguien que no pilla los memes o la jerga del momento; también olkeukeu. La edad da igual -un adolescente desconectado también cuenta- y se usa mucho más para etiquetarse uno mismo tras perderse un chiste que para burlarse de otros.", "ja": "最新のミームや流行語が分からない人。オルククとも言う。実年齢とは無関係で10代でも流行に遅れれば当てはまり、他人をからかうより、分からなかった自分を下げて呼ぶときにずっとよく使う。", "vi": "Người không hiểu meme hay tiếng lóng mới nhất; còn gọi là olkeukeu. Tuổi tác không quan trọng - thiếu niên tụt hậu cũng tính - và người ta hay dùng để tự nhận sau khi không hiểu một câu đùa hơn là để chê ai."}}], "created_at": "2026-09-04T08:00:00+00:00", "short_desc": "요즘 유행을 못 따라가는 사람 (영크크의 반대말)", "usage_i18n": {"de": "Selbstironisch, wenn man ein neues Meme nicht kapiert; auf andere gemünzt klingt es neckend - besser nur unter engen Freunden.", "en": "Used self-deprecatingly when a new meme goes over your head; pointed at someone else it teases, so it is safer among close friends.", "es": "Se usa con autoburla cuando un meme nuevo se te escapa; dirigido a otro suena a pulla, así que mejor entre amigos.", "ja": "新しいミームが分からなかったときに自嘲的に使う。他人に使うとからかう響きになるので、親しい間柄でなければ控えたほうがいい。", "vi": "Dùng để tự giễu khi không hiểu meme mới; nói về người khác thì thành trêu, nên chỉ hợp với bạn thân."}, "origin_i18n": {"de": "Als Gegenwort zu yeongkeukeu (vom CORTIS-Song Young Creator Crew) gebildet, indem neuk- für alt eingesetzt wurde; verbreitet als Online-Meme 2026. Manche Quellen lesen es als Kurzform von neulgeun keukeukeu (altes Lachen), doch die Antonym-Lesart ist verbreiteter und die Frage ist ungeklärt.", "en": "Coined as the antonym of yeongkeukeu (from the CORTIS song Young Creator Crew) by swapping in neuk-, meaning old; it spread as a 2026 online meme. Some sources instead read it as a contraction of neulgeun keukeukeu (old laughter), but the antonym reading is the more common one and the question is not settled.", "es": "Acuñado como antónimo de yeongkeukeu (del tema Young Creator Crew de CORTIS) cambiando el inicio por neuk-, viejo; se difundió como meme en 2026. Algunas fuentes lo leen como contracción de neulgeun keukeukeu (risa vieja), pero la lectura como antónimo es la más común y la cuestión no está zanjada.", "ja": "CORTISの曲Young Creator Crew由来のヨンククに「늙-(老いた)」を付けて作った反対語で、2026年のオンラインミームとして広まった。「늙은 크크크(老いた笑い声)」の略という説もあるが、ヨンククの対称形とする説明のほうが広く使われており、どちらが正しいかは未確定。", "vi": "Được tạo ra làm từ trái nghĩa của yeongkeukeu (từ ca khúc Young Creator Crew của CORTIS) bằng cách thay bằng neuk-, nghĩa là già; lan rộng thành meme mạng năm 2026. Một số nguồn lại hiểu là rút gọn của neulgeun keukeukeu (tiếng cười già), nhưng cách hiểu trái nghĩa phổ biến hơn và vẫn chưa ngã ngũ."}, "romanization": "Neuk-keu-keu", "translations": [{"lang": "🇺🇸 EN", "text": "Out of the loop (on memes and trends)"}, {"lang": "🇯🇵 JA", "text": "流行についていけない人"}, {"lang": "🇨🇳 ZH", "text": "跟不上潮流的人"}, {"lang": "🇻🇳 VI", "text": "Người không bắt kịp trend"}, {"lang": "🇪🇸 ES", "text": "Desconectado de las tendencias"}, {"lang": "🇩🇪 DE", "text": "Trend-Nachzügler"}], "pronunciation": "[늑크크]", "related_words": ["영크크", "아싸", "현타"], "short_desc_i18n": {"de": "Jemand, der bei Trends nicht mitkommt (Gegenteil von yeongkeukeu)", "en": "Someone who cannot keep up with trends - the opposite of yeongkeukeu", "es": "Alguien que no sigue el ritmo de las tendencias (lo contrario de yeongkeukeu)", "ja": "最近の流行についていけない人(ヨンククの反対語)", "vi": "Người không bắt kịp trend (trái nghĩa với yeongkeukeu)"}}$json$::jsonb);

insert into public.words select * from jsonb_populate_record(null::public.words, $json${"id": "222", "word": "낄끼빠빠", "likes": 0, "saves": 0, "usage": "주로 친구 사이에서 가볍게 핀잔줄 때. 윗사람에게 쓰면 무례하게 들린다.", "origin": "2010년대 중반 인터넷 커뮤니티와 10~20대 사이에서 퍼진 네 글자 줄임말. 2016년 언론 기사에 '빼박캔트', '금사빠'와 함께 세대 간 소통 문제를 다루는 예시로 이미 등장했다.", "category": "new-slang", "meanings": [{"type": "표현", "examples": [{"de": "Alter, lies mal die Situation. Jetzt ist nicht dein Moment.", "es": "Tío, capta el ambiente. Este no es tu momento para meterte.", "ja": "おい、空気読もうよ。今は入るとこじゃない。", "vi": "Ê, đọc không khí đi. Giờ không phải lúc chen vào đâu.", "eng": "Dude, read the room. This is not your moment to jump in.", "kor": "야, 낄끼빠빠 좀 하자. 지금 낄 자리 아니야."}], "definition": "'낄 때 끼고 빠질 때 빠져라'의 앞 글자를 딴 줄임말. 분위기를 파악하고 나설 때와 물러날 때를 가리라는 뜻으로, 눈치 없이 끼어드는 사람에게 핀잔을 줄 때 쓴다.", "definition_i18n": {"de": "Kurzform von \"misch dich ein, wenn es passt, und halt dich raus, wenn nicht\". Man sagt es jemandem, der die Situation nicht erfasst und sich ständig einmischt.", "en": "An acronym-style contraction of \"join in when you should, step back when you should.\" Used to tell someone to read the room — usually as a jab at a person who keeps butting in.", "es": "Contracción de \"métete cuando toca y retírate cuando toca\". Se usa para decirle a alguien que capte el ambiente, normalmente como reproche a quien se entromete sin leer la situación.", "ja": "「入る時は入り、引く時は引け」の頭文字を取った略語。空気を読んで出る時と引く時を見極めろという意味で、無神経に割り込む人をたしなめる時に使う。", "vi": "Viết tắt của \"lúc nên tham gia thì tham gia, lúc nên rút thì rút\". Dùng để nhắc ai đó biết đọc không khí, thường là lời trách người cứ chen vào vô duyên."}}], "created_at": "2026-09-04T08:00:00+00:00", "short_desc": "낄 때 끼고 빠질 때 빠져라 — 눈치껏 행동하라는 말", "usage_i18n": {"de": "Meist ein lockerer Spruch unter Freunden; gegenüber Älteren oder Vorgesetzten klingt es unhöflich.", "en": "Mostly a light jab between friends; saying it to someone older or senior sounds rude.", "es": "Sobre todo una pulla ligera entre amigos; decírselo a un superior suena grosero.", "ja": "主に友達同士の軽いツッコミ。目上の人に使うと失礼に聞こえる。", "vi": "Chủ yếu là lời trêu nhẹ giữa bạn bè; nói với người lớn tuổi hơn sẽ thành hỗn."}, "origin_i18n": {"de": "Eine viersilbige Kurzform, die Mitte der 2010er in Online-Communities und unter Jugendlichen aufkam; 2016 tauchte sie in der Presse neben 빼박캔트 und 금사빠 als Beispiel für Sprachlücken zwischen Generationen auf.", "en": "A four-syllable contraction that spread through online communities and teens/20s in the mid-2010s; by 2016 it already appeared in press coverage alongside 빼박캔트 and 금사빠 as an example of generational language gaps.", "es": "Contracción de cuatro sílabas difundida en comunidades online y entre adolescentes y veinteañeros a mediados de los 2010; en 2016 ya salía en prensa junto a 빼박캔트 y 금사빠 como ejemplo de brecha generacional.", "ja": "2010年代半ばにネットコミュニティと10〜20代の間で広まった4文字の略語。2016年には新聞記事で「ペバクケント」「クムサパ」と並び世代間の言葉のギャップの例として取り上げられた。", "vi": "Từ viết tắt bốn âm tiết lan trong cộng đồng mạng và giới trẻ giữa thập niên 2010; đến 2016 đã xuất hiện trên báo cùng 빼박캔트 và 금사빠 như ví dụ về khoảng cách ngôn ngữ giữa các thế hệ."}, "romanization": "Kkil-kki-ppa-ppa", "translations": [{"lang": "🇺🇸 EN", "text": "Read the room"}, {"lang": "🇯🇵 JA", "text": "空気を読め"}, {"lang": "🇨🇳 ZH", "text": "看场合行事"}, {"lang": "🇻🇳 VI", "text": "Biết lúc vào lúc ra"}, {"lang": "🇪🇸 ES", "text": "Capta el ambiente"}, {"lang": "🇩🇪 DE", "text": "Lies die Situation"}], "pronunciation": "[낄끼빠빠]", "related_words": ["알잘딱깔센", "TMI"], "short_desc_i18n": {"de": "Wisse, wann du dich einmischst und wann du dich raushältst", "en": "Know when to join in and when to back off", "es": "Métete cuando toca y retírate cuando toca", "ja": "入る時は入り、引く時は引け — 空気を読めという意味", "vi": "Biết lúc nào nên tham gia, lúc nào nên rút lui"}}$json$::jsonb);

insert into public.words select * from jsonb_populate_record(null::public.words, $json${"id": "223", "word": "국룰", "likes": 0, "saves": 0, "usage": "'~는 국룰'처럼 명사 뒤에 붙여 쓴다. 음식 조합, 회식 자리, 게임 매너 등 사소한 관행에 주로 쓴다.", "origin": "'국민'의 '국'에 영어 rule을 붙인 혼종어. 국립국어원 온라인가나다 답변도 어근끼리 결합한 합성어로 설명한다. 2020년 무렵 온라인에서 본격적으로 유행하기 시작했다.", "category": "new-slang", "meanings": [{"type": "명사", "examples": [{"de": "Am Umzugstag Jajangmyeon bestellen ist doch die nationale Regel, oder?", "es": "Pedir jajangmyeon el día de la mudanza es la regla nacional, ¿no?", "ja": "引っ越したらチャジャンミョン頼むのが国民ルールじゃない?", "vi": "Chuyển nhà là phải gọi jajangmyeon, luật quốc dân mà?", "eng": "Ordering jajangmyeon on moving day is basically the national rule, right?", "kor": "이사하면 짜장면 시키는 게 국룰 아니야?"}], "definition": "한자 '국(國)'과 영어 'rule'을 합친 혼종어로 '국민 룰'을 줄인 말. 법이나 규정은 아니지만 대부분이 당연하게 받아들이는 관행을 가리킨다. 진지한 규범이라기보다 농담 섞인 말투로 쓴다.", "definition_i18n": {"de": "Eine Mischbildung aus sinokoreanisch 국 (national) und englisch rule, kurz für \"nationale Regel\". Gemeint ist eine Gepflogenheit, die fast alle als selbstverständlich ansehen, obwohl sie nirgends festgelegt ist — halb im Scherz gesagt.", "en": "A hybrid of Sino-Korean 국(national) and English rule, short for \"national rule.\" It means a practice almost everyone treats as obvious, though it is nothing official — and it is said half-jokingly.", "es": "Híbrido del sino-coreano 국 (nacional) y el inglés rule, abreviatura de \"regla nacional\". Designa una costumbre que casi todos dan por obvia sin ser nada oficial, y se dice medio en broma.", "ja": "漢字の「国」と英語の「rule」を合わせた混種語で「国民ルール」の略。法でも規則でもないが、ほぼ全員が当然と受け止める慣行を指す。真面目な規範というより冗談めかして使う。", "vi": "Từ lai giữa 국 (quốc) gốc Hán và rule tiếng Anh, viết tắt của \"luật quốc dân\". Chỉ thói quen mà hầu như ai cũng coi là hiển nhiên dù chẳng chính thức, và thường nói nửa đùa."}}], "created_at": "2026-09-04T08:00:00+00:00", "short_desc": "다들 당연하게 여기는 불문율", "usage_i18n": {"de": "Wird als \"X ist 국룰\" hinter ein Nomen gesetzt; meist für kleine Konventionen — Essenskombis, Verhalten beim Firmenessen, Gaming-Etikette.", "en": "Used as \"X is 국룰\" after a noun; typically for small conventions — food pairings, dinner-party etiquette, gaming manners.", "es": "Se usa como \"X es 국룰\" tras un sustantivo; suele aplicarse a convenciones menores: combinaciones de comida, etiqueta en cenas, modales en videojuegos.", "ja": "「〜は国民ルール」のように名詞の後に付ける。食べ合わせ、飲み会の作法、ゲームのマナーなど些細な慣行に使う。", "vi": "Dùng theo kiểu \"X là 국룰\" sau danh từ; thường cho các thói quen nhỏ như cách kết hợp món ăn, phép tắc tiệc tùng, văn hóa chơi game."}, "origin_i18n": {"de": "Gebildet aus englisch rule und 국 von 국민 (Volk); das Nationale Institut für Koreanische Sprache beschreibt es als Kompositum zweier Wortwurzeln. Online setzte es sich um 2020 durch.", "en": "Formed by attaching English rule to 국 from 국민 (the people); the National Institute of Korean Language describes it as a compound of two roots. It took off online around 2020.", "es": "Se forma uniendo el inglés rule a 국 de 국민 (pueblo); el Instituto Nacional de la Lengua Coreana lo describe como compuesto de dos raíces. Se popularizó en internet hacia 2020.", "ja": "「国民」の「国」に英語のruleを付けた混種語。国立国語院の回答でも語根同士の合成語と説明される。2020年前後にネットで本格的に流行し始めた。", "vi": "Ghép rule tiếng Anh với 국 trong 국민 (quốc dân); Viện Quốc ngữ Hàn Quốc mô tả đây là từ ghép hai gốc. Bùng nổ trên mạng khoảng năm 2020."}, "romanization": "Gung-nul", "translations": [{"lang": "🇺🇸 EN", "text": "Unwritten rule / the default"}, {"lang": "🇯🇵 JA", "text": "暗黙のルール"}, {"lang": "🇨🇳 ZH", "text": "公认的潜规则"}, {"lang": "🇻🇳 VI", "text": "Luật bất thành văn"}, {"lang": "🇪🇸 ES", "text": "Regla no escrita"}, {"lang": "🇩🇪 DE", "text": "Ungeschriebene Regel"}], "pronunciation": "[궁눌]", "related_words": ["사바사", "갓생"], "short_desc_i18n": {"de": "Die ungeschriebene Regel, die alle befolgen", "en": "The unwritten rule everyone just follows", "es": "La regla no escrita que todos dan por hecha", "ja": "みんなが当然と思っている暗黙のルール", "vi": "Luật bất thành văn ai cũng mặc định"}}$json$::jsonb);

insert into public.words select * from jsonb_populate_record(null::public.words, $json${"id": "224", "word": "관종", "likes": 0, "saves": 0, "usage": "기본적으로 비하 표현이라 당사자 앞에서 쓰면 싸움 난다. 친구끼리 장난으로, 또는 자기 자신에게 '나 관종인가 봐'처럼 쓰는 건 무난하다.", "origin": "'관심종자' 또는 '관심병 종자'의 준말로 2010년대 초 인터넷 커뮤니티에서 굳어졌다. '종자'는 부류·족속을 낮잡아 이르는 말. 원래는 SNS에 일상을 전시하는 사람을 비난하는 부정적 용어였으나, 2020년대 들어 '관종력'이 하나의 능력으로 재평가되는 흐름도 생겼다.", "category": "new-slang", "meanings": [{"type": "명사", "examples": [{"de": "Wir haben sie als Aufmerksamkeitsjunkie beschimpft — jetzt sind sie Influencer.", "es": "Le llamábamos ansioso de atención y al final se hizo influencer.", "ja": "かまってちゃんって言ってたのに、結局あの子インフルエンサーになった。", "vi": "Cả đám chê nó thích thể hiện, cuối cùng nó thành influencer.", "eng": "We called them an attention seeker, and now they are an influencer.", "kor": "관종이라고 욕했는데 결국 걔가 인플루언서 됐어."}], "definition": "'관심종자'(관심 + 종자)의 줄임말. 남의 관심을 끌려는 욕구를 노골적으로 드러내고 실제 행동으로 옮겨 주변을 불편하게 하는 사람을 비꼬는 말. 최근에는 자기 PR에 적극적인 사람을 반쯤 긍정적으로 부를 때도 쓴다.", "definition_i18n": {"de": "Kurz für 관심종자 (Aufmerksamkeit + Samen), spöttisch für jemanden, der offen nach Aufmerksamkeit giert und damit anderen auf die Nerven geht. Neuerdings auch halb anerkennend für Leute, die sich schamlos selbst vermarkten.", "en": "Short for 관심종자 (attention + seed), mocking someone who openly craves attention and acts on it until others get uncomfortable. Lately it is also used half-approvingly for people who are shameless about self-promotion.", "es": "Abreviatura de 관심종자 (atención + semilla), burla hacia quien ansía atención abiertamente y actúa hasta incomodar a los demás. Últimamente también se usa medio en positivo para quien no tiene reparo en autopromocionarse.", "ja": "「関心種子」の略で、注目されたい欲を露骨に出し行動に移して周囲を困らせる人を皮肉る言葉。最近は自己PRに積極的な人を半ば肯定的に呼ぶ場合もある。", "vi": "Viết tắt của 관심종자 (chú ý + giống loài), mỉa mai người lộ liễu thèm được chú ý và làm tới mức khiến người khác khó chịu. Gần đây còn dùng nửa tích cực cho người mạnh dạn PR bản thân."}}], "created_at": "2026-09-04T08:00:00+00:00", "short_desc": "관심받으려고 과하게 행동하는 사람", "usage_i18n": {"de": "Im Kern eine Beleidigung — direkt gesagt gibt es Streit. Unter engen Freunden im Scherz oder über sich selbst (\"ich bin wohl aufmerksamkeitssüchtig\") geht es.", "en": "It is an insult at heart, so saying it to someone's face starts fights. Joking among close friends, or about yourself (\"guess I am an attention seeker\"), is fine.", "es": "Es un insulto de base, así que decírselo a la cara provoca broncas. En broma entre amigos, o sobre uno mismo (\"creo que soy un ansioso de atención\"), no pasa nada.", "ja": "基本的に侮蔑語なので本人の前で使うと喧嘩になる。友達同士の冗談や「私かまってちゃんかも」と自分に使うのは問題ない。", "vi": "Vốn là từ chê nên nói thẳng vào mặt ai đó là gây sự. Đùa giữa bạn thân hoặc tự nói về mình (\"chắc mình thích thể hiện thật\") thì ổn."}, "origin_i18n": {"de": "Zusammenziehung von 관심종자 bzw. 관심병 종자, seit Anfang der 2010er in Online-Communities etabliert; 종자 (Samen/Sorte) ist ein abwertendes Wort für einen Menschenschlag. Ursprünglich rein negativ gegen Social-Media-Selbstdarsteller gerichtet, wurde die Aufmerksamkeitssucht in den 2020ern teils als Fähigkeit umgedeutet.", "en": "A contraction of 관심종자 or 관심병 종자, settled in online communities in the early 2010s; 종자 (seed/breed) is a belittling word for a type of person. Originally a purely negative jab at people who display their lives on social media, but in the 2020s attention-seeking got partly reframed as a marketable skill.", "es": "Contracción de 관심종자 o 관심병 종자, asentada en comunidades online a principios de los 2010; 종자 (semilla/casta) es un término despectivo para un tipo de persona. Empezó como crítica a quien exhibe su vida en redes, pero en los 2020 esa ansia de atención se ha reinterpretado en parte como una habilidad.", "ja": "「関心種子」「関心病種子」の略で2010年代初頭にネットコミュニティで定着。「種子」は人の類を見下して言う語。元はSNSに日常を晒す人を非難する否定的な語だったが、2020年代には注目を集める力が一種の能力として再評価される流れも生まれた。", "vi": "Rút gọn từ 관심종자 hay 관심병 종자, định hình trong cộng đồng mạng đầu thập niên 2010; 종자 (hạt giống/nòi) là từ hạ thấp chỉ một hạng người. Ban đầu thuần chê người khoe cuộc sống trên mạng xã hội, nhưng sang thập niên 2020 khả năng hút chú ý phần nào được xem là một kỹ năng."}, "romanization": "Gwan-jong", "translations": [{"lang": "🇺🇸 EN", "text": "Attention seeker / attention whore (vulgar)"}, {"lang": "🇯🇵 JA", "text": "かまってちゃん"}, {"lang": "🇨🇳 ZH", "text": "戏精 / 求关注的人"}, {"lang": "🇻🇳 VI", "text": "Người thích thể hiện"}, {"lang": "🇪🇸 ES", "text": "Ansioso de atención"}, {"lang": "🇩🇪 DE", "text": "Aufmerksamkeitsjunkie"}], "pronunciation": "[관종]", "related_words": ["인싸", "핵인싸", "아싸"], "short_desc_i18n": {"de": "Jemand, der für Aufmerksamkeit übertreibt", "en": "Someone who overdoes it for attention", "es": "Alguien que se pasa buscando atención", "ja": "注目されたくて過剰に振る舞う人", "vi": "Người làm quá lên để được chú ý"}}$json$::jsonb);

insert into public.words select * from jsonb_populate_record(null::public.words, $json${"id": "225", "word": "삼귀다", "likes": 0, "saves": 0, "usage": "'삼귀는 중이야', '삼귄 지 한 달 됐어'처럼 동사로 활용한다. 친구들끼리 연애 상담할 때 주로 쓴다.", "origin": "'사귀다'의 첫 음절 '사'를 숫자 4로 보고, 그에 못 미친다는 뜻으로 한 단계 낮춰 3(삼)으로 바꾼 말장난. 2019년 언론에 신조어로 소개되며 널리 알려졌다.", "category": "new-slang", "meanings": [{"type": "동사", "examples": [{"de": "Wir sind nicht zusammen, wir sind in der Vorstufe, okay?", "es": "No estamos saliendo, estamos en el paso previo, ¿vale?", "ja": "付き合ってるんじゃなくて、その一歩手前だってば。", "vi": "Chưa yêu đâu, mới đang \"gần yêu\" thôi mà!", "eng": "We are not dating, we are pre-dating, okay?", "kor": "사귀는 거 아니고 삼귀는 중이라니까?"}], "definition": "아직 연인은 아니지만 친구보다는 가까운, 서로를 알아가는 상태를 뜻한다. '썸 타다'와 거의 같은 뜻이지만 '사귀다'와 운을 맞춘 말장난이라 더 장난스럽고 귀여운 어감이다.", "definition_i18n": {"de": "Näher als Freundschaft, aber noch kein Paar — man tastet sich ab. Fast bedeutungsgleich mit 썸 타다, klingt durch das Wortspiel mit 사귀다 aber verspielter und niedlicher.", "en": "Being closer than friends but not yet a couple — still feeling each other out. Nearly identical to 썸 타다, but because it rhymes with 사귀다 it sounds more playful and cute.", "es": "Estar más cerca que amigos pero sin ser pareja, aún tanteándose. Casi idéntico a 썸 타다, pero al rimar con 사귀다 suena más juguetón y tierno.", "ja": "まだ恋人ではないが友達より近い、互いを知っていく状態。「썸 타다」とほぼ同義だが「사귀다」と韻を踏んだ言葉遊びなので、より遊び心があり可愛い語感。", "vi": "Thân hơn bạn nhưng chưa phải người yêu, vẫn đang tìm hiểu nhau. Gần như đồng nghĩa với 썸 타다, nhưng vì chơi chữ với 사귀다 nên nghe tinh nghịch và dễ thương hơn."}}], "created_at": "2026-09-04T08:00:00+00:00", "short_desc": "사귀기 직전, 서로 알아가는 썸 단계", "usage_i18n": {"de": "Wird wie ein normales Verb gebeugt: 삼귀는 중이야, 삼귄 지 한 달 됐어. Vor allem beim Austausch über Liebesdinge unter Freunden.", "en": "Conjugated like a normal verb: 삼귀는 중이야 (we are pre-dating), 삼귄 지 한 달 됐어 (it has been a month). Mostly used when swapping love-life updates with friends.", "es": "Se conjuga como verbo normal: 삼귀는 중이야, 삼귄 지 한 달 됐어. Se usa sobre todo al contar cosas de amores entre amigos.", "ja": "「삼귀는 중이야」「삼귄 지 한 달 됐어」のように動詞として活用する。友達との恋愛相談でよく使う。", "vi": "Chia như động từ thường: 삼귀는 중이야, 삼귄 지 한 달 됐어. Chủ yếu dùng khi tâm sự chuyện yêu đương với bạn bè."}, "origin_i18n": {"de": "Ein Wortspiel: Das 사 in 사귀다 (zusammen sein) wird als Zahl 4 gelesen und auf 3 (삼) heruntergestuft — \"noch nicht ganz so weit\". Bekannt wurde es, als die koreanische Presse es 2019 als Neuwort vorstellte.", "en": "A pun that reads the 사 in 사귀다 (to date) as the number 4 and knocks it down to 3 (삼) to mean \"not quite there yet.\" It reached the mainstream when Korean press covered it as a new coinage in 2019.", "es": "Juego de palabras que lee el 사 de 사귀다 (salir con alguien) como el número 4 y lo baja a 3 (삼) para decir \"todavía no llega\". Se difundió cuando la prensa coreana lo presentó como neologismo en 2019.", "ja": "「사귀다」の「사」を数字の4と見立て、そこに至らないという意味で3(삼)に下げた言葉遊び。2019年に新造語としてメディアで紹介され広く知られた。", "vi": "Chơi chữ: đọc 사 trong 사귀다 (hẹn hò) như số 4 rồi hạ xuống 3 (삼) với nghĩa \"chưa tới mức đó\". Được biết rộng rãi khi báo chí Hàn giới thiệu như từ mới năm 2019."}, "romanization": "Sam-gwi-da", "translations": [{"lang": "🇺🇸 EN", "text": "Pre-dating / talking stage"}, {"lang": "🇯🇵 JA", "text": "付き合う一歩手前"}, {"lang": "🇨🇳 ZH", "text": "暧昧期"}, {"lang": "🇻🇳 VI", "text": "Giai đoạn gần yêu"}, {"lang": "🇪🇸 ES", "text": "Fase previa a salir"}, {"lang": "🇩🇪 DE", "text": "Vorstufe zur Beziehung"}], "pronunciation": "[삼귀다]", "related_words": ["금사빠", "심쿵"], "short_desc_i18n": {"de": "Die Fast-Beziehung kurz vor dem Offiziellwerden", "en": "The almost-dating stage, just before making it official", "es": "La fase de casi salir juntos, justo antes de oficializarlo", "ja": "付き合う一歩手前、お互いを探り合う段階", "vi": "Giai đoạn gần yêu, ngay trước khi chính thức"}}$json$::jsonb);

insert into public.words select * from jsonb_populate_record(null::public.words, $json${"id": "226", "word": "어그로", "likes": 0, "saves": 0, "usage": "'어그로 끌다', '어그로 끌지 마'처럼 쓴다. 커뮤니티·유튜브 댓글에서 매우 흔하며, 상대를 관종보다 강하게 비난하는 뉘앙스다.", "origin": "영어 aggravation(도발·악화)에서 온 말. 원래 MMORPG 용어로, 몬스터가 어떤 플레이어를 공격 대상으로 삼게 만드는 시스템을 가리켰고 에버퀘스트에서 정립돼 다른 게임으로 퍼졌다. 탱커가 일부러 몬스터의 주의를 끄는 '어그로 관리'에서 '주의를 끈다'는 뜻만 떨어져 나와 인터넷 일상어가 됐다.", "category": "new-slang", "meanings": [{"type": "명사", "examples": [{"de": "Allein die Überschrift ist Clickbait — klick da gar nicht drauf.", "es": "Solo el titular ya es cebo puro, ni lo abras.", "ja": "タイトルからしてただの煽りだよ、クリックもするな。", "vi": "Nhìn tiêu đề là biết câu view rồi, đừng bấm vào.", "eng": "That headline is pure bait — do not even click it.", "kor": "제목만 봐도 딱 어그로네, 클릭도 하지 마."}], "definition": "'어그로를 끌다' 형태로 쓰며, 목적을 갖고 남의 주의를 자극적으로 끄는 행동을 뜻한다. 자극적인 제목, 도발적인 댓글, 싸움 거는 말투 등이 전형이다. 일상어로 넘어오면서 거의 항상 부정적인 뜻으로 쓴다.", "definition_i18n": {"de": "Wird als 어그로를 끌다 gebraucht: gezielt Aufmerksamkeit provozieren — Clickbait-Titel, aufhetzende Kommentare, Streit suchen. Seit es aus dem Gaming in die Alltagssprache übergegangen ist, fast durchweg negativ.", "en": "Used as 어그로를 끌다 — deliberately provoking others' attention for some purpose: clickbait titles, inflammatory comments, picking fights. Once it moved out of gaming into everyday speech it became almost entirely negative.", "es": "Se usa como 어그로를 끌다: provocar a propósito la atención ajena con titulares sensacionalistas, comentarios incendiarios o buscando pelea. Al pasar del videojuego al habla cotidiana quedó casi siempre en sentido negativo.", "ja": "「어그로를 끌다」の形で使い、目的を持って人の注意を刺激的に引く行動を指す。煽りタイトル、挑発的なコメント、喧嘩腰の口調などが典型。日常語になってからはほぼ常に否定的に使われる。", "vi": "Dùng dạng 어그로를 끌다 — cố ý khiêu khích để hút sự chú ý: tiêu đề giật gân, bình luận kích động, giọng điệu gây sự. Khi ra khỏi game vào đời thường, nó gần như luôn mang nghĩa xấu."}}], "created_at": "2026-09-04T08:00:00+00:00", "short_desc": "관심 끌려고 일부러 자극적으로 구는 것", "usage_i18n": {"de": "Wird als 어그로 끌다 / 어그로 끌지 마 verwendet. In Foren und YouTube-Kommentaren sehr verbreitet und ein härterer Vorwurf als 관종.", "en": "Used as 어그로 끌다 / 어그로 끌지 마. Extremely common in forums and YouTube comments, and a harsher accusation than calling someone 관종.", "es": "Se usa como 어그로 끌다 / 어그로 끌지 마. Muy común en foros y comentarios de YouTube, y es una acusación más dura que llamar a alguien 관종.", "ja": "「어그로 끌다」「어그로 끌지 마」のように使う。コミュニティやYouTubeのコメントで非常によく見られ、「관종」より強い非難のニュアンス。", "vi": "Dùng như 어그로 끌다 / 어그로 끌지 마. Rất phổ biến ở diễn đàn và bình luận YouTube, và nặng lời hơn gọi ai đó là 관종."}, "origin_i18n": {"de": "Von englisch aggravation. Ursprünglich ein MMORPG-Begriff für das System, nach dem ein Monster sein Angriffsziel wählt — in EverQuest geprägt und von anderen Spielen übernommen. Von der Tank-Aufgabe, die Aufmerksamkeit des Monsters gezielt zu ziehen, blieb im Alltagsinternet nur die Bedeutung \"Aufmerksamkeit erregen\".", "en": "From English aggravation. It began as an MMORPG mechanic — how a monster picks which player to attack — codified in EverQuest and copied by other games. From the tank's job of deliberately pulling a monster's attention, only the sense of \"drawing attention\" survived into everyday internet Korean.", "es": "Del inglés aggravation. Nació como mecánica de MMORPG —cómo un monstruo elige a qué jugador atacar—, fijada en EverQuest y copiada por otros juegos. De la tarea del tanque de atraer al monstruo a propósito solo sobrevivió el sentido de \"atraer la atención\" en el coreano coloquial de internet.", "ja": "英語のaggravation(挑発・悪化)から。元はMMORPGの用語で、モンスターがどのプレイヤーを攻撃対象にするかのシステムを指し、エバークエストで定着し他ゲームに広がった。タンクがわざとモンスターの注意を引く「アグロ管理」から「注意を引く」意味だけが独立し、ネットの日常語になった。", "vi": "Từ aggravation trong tiếng Anh. Vốn là thuật ngữ MMORPG chỉ cơ chế quái chọn người chơi để tấn công, định hình trong EverQuest rồi lan sang game khác. Từ việc tank cố ý kéo sự chú ý của quái, chỉ nghĩa \"kéo sự chú ý\" còn lại trong tiếng lóng mạng."}, "romanization": "Eo-geu-ro", "translations": [{"lang": "🇺🇸 EN", "text": "Baiting / trolling for attention"}, {"lang": "🇯🇵 JA", "text": "アグロ / 煽り"}, {"lang": "🇨🇳 ZH", "text": "拉仇恨 / 带节奏"}, {"lang": "🇻🇳 VI", "text": "Câu view, khiêu khích"}, {"lang": "🇪🇸 ES", "text": "Provocar / hacer cebo"}, {"lang": "🇩🇪 DE", "text": "Provozieren / Clickbait"}], "pronunciation": "[어그로]", "related_words": ["억까", "바이럴"], "short_desc_i18n": {"de": "Absichtliches Provozieren, um Aufmerksamkeit zu bekommen", "en": "Deliberately stirring things up to get attention", "es": "Provocar a propósito para llamar la atención", "ja": "注目を集めるためにわざと煽ること", "vi": "Cố tình khiêu khích để gây chú ý"}}$json$::jsonb);

commit;

